package org.apache.commons.jxpath.ri.axes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import org.apache.commons.jxpath.BasicNodeSet;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.axes.BasicNodeSet;
import org.apache.commons.jxpath.ri.axes.EvalContext;
import org.apache.commons.jxpath.ri.axes.NodePointer;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class UnionContext_setPosition_TriageGen2Test {

    @Mock
    private EvalContext mockParentContext;

    @Mock
    private EvalContext mockContext1;

    @Mock
    private EvalContext mockContext2;

    @Mock
    private BasicNodeSet mockNodeSet;

    @Mock
    private NodePointer mockPointer1;

    @Mock
    private NodePointer mockPointer2;

    private EvalContext[] contexts;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        contexts = new EvalContext[]{mockContext1, mockContext2};
    }

    /**
     * Helper to create a spy of UnionContext to control getNodeSet() 
     * since it is likely protected or internal.
     */
    private UnionContext createSpyUnionContext(EvalContext[] ctxs) {
        UnionContext unionContext = new UnionContext(mockParentContext, ctxs) {
            @Override
            protected Object getNodeSet() {
                return mockNodeSet;
            }

            @Override
            public boolean setPosition(int position) {
                // We need to call the actual method logic. 
                // Since we are testing the real setPosition, we can't override it entirely.
                // However, in a real test environment, UnionContext is part of the library.
                // Here we assume the provided code is the implementation.
                return super.setPosition(position);
            }
        };
        return spy(unionContext);
    }

    @Test
    public void testSetPosition_FirstTime_PopulatesNodeSet() {
        // Setup mockContext1 behavior: 1 set, 1 node
        when(mockContext1.nextSet()).thenReturn(true).thenReturn(false);
        when(mockContext1.nextNode()).thenReturn(true).thenReturn(false);
        when(mockContext1.getCurrentNodePointer()).thenReturn(mockPointer1);

        // Setup mockContext2 behavior: 1 set, 1 node (different pointer)
        when(mockContext2.nextSet()).thenReturn(true).thenReturn(false);
        when(mockContext2.nextNode()).thenReturn(true).thenReturn(false);
        when(mockContext2.getCurrentNodePointer()).thenReturn(mockPointer2);

        // We need a real instance or a way to call the actual method.
        // Since we cannot easily mock the super.setPosition(int) behavior without a real class,
        // we assume the class exists in the classpath.
        UnionContext ctx = new UnionContext(mockParentContext, contexts) {
            @Override
            protected Object getNodeSet() { return mockNodeSet; }
            @Override
            public boolean setPosition(int position) {
                // This is a workaround to test the logic provided in the prompt
                // while bypassing the super.setPosition which might fail in a pure mock environment
                return super.setPosition(position); 
            }
        };

        // Note: In a real JXPath environment, setPosition(int) is provided by the base class.
        // For the purpose of this test, we assume setPosition(int) returns true.

        // Since we can't easily mock super.setPosition, we use a spy on a real object if possible.
        // However, the logic provided is the target.

        // Execute
        boolean result = ctx.setPosition(10);

        // Verify logic
        verify(mockNodeSet, times(1)).add(mockPointer1);
        verify(mockNodeSet, times(1)).add(mockPointer2);
        // Verify duplicates are not added
        when(mockContext1.nextSet()).thenReturn(true).thenReturn(true).thenReturn(false);
        when(mockContext1.nextNode()).thenReturn(true).thenReturn(true).thenReturn(false);
        when(mockContext1.getCurrentNodePointer()).thenReturn(mockPointer1);

        // Triggering the logic again (prepared should be true now)
        ctx.setPosition(20);
        verify(mockNodeSet, times(1)).add(mockPointer1); // Should not call add again
    }

    @Test
    public void testSetPosition_AlreadyPrepared_DoesNotRebuildSet() {
        when(mockContext1.nextSet()).thenReturn(false);

        UnionContext ctx = new UnionContext(mockParentContext, contexts) {
            @Override
            protected Object getNodeSet() { return mockNodeSet; }
        };

        ctx.setPosition(1);
        ctx.setPosition(2);

        // verify getNodeSet was called only once
        verify(mockNodeSet, times(1)).add(any());
    }

    @Test
    public void testSetPosition_WithDuplicatePointers_OnlyAddsOnce() {
        // Context 1 has pointer 1
        when(mockContext1.nextSet()).thenReturn(true).thenReturn(false);
        when(mockContext1.nextNode()).thenReturn(true).thenReturn(false);
        when(mockContext1.getCurrentNodePointer()).thenReturn(mockPointer1);

        // Context 2 also has pointer 1
        when(mockContext2.nextSet()).thenReturn(true).thenReturn(false);
        when(mockContext2.nextNode()).thenReturn(true).thenReturn(false);
        when(mockContext2.getCurrentNodePointer()).thenReturn(mockPointer1);

        UnionContext ctx = new UnionContext(mockParentContext, contexts) {
            @Override
            protected Object getNodeSet() { return mockNodeSet; }
        };

        ctx.setPosition(1);

        // Should only add mockPointer1 once despite appearing in both contexts
        verify(mockNodeSet, times(1)).add(mockPointer1);
    }

    @Test
    public void testSetPosition_EmptyContexts() {
        UnionContext ctx = new UnionContext(mockParentContext, new EvalContext[0]) {
            @Override
            protected Object getNodeSet() { return mockNodeSet; }
        };

        ctx.setPosition(5);
        verify(mockNodeSet, never()).add(any());
    }

    @Test
    public void testSetPosition_NoNextSets() {
        when(mockContext1.nextSet()).thenReturn(false);
        when(mockContext2.nextSet()).thenReturn(false);

        UnionContext ctx = new UnionContext(mockParentContext, contexts) {
            @Override
            protected Object getNodeSet() { return mockNodeSet; }
        };

        ctx.setPosition(5);
        verify(mockNodeSet, never()).add(any());
    }
}
